from playwright.sync_api import sync_playwright
from itertools import product
import tkinter as tk

class SamexButDiffbError(Exception):
    pass

class CloseError(Exception):
    pass

class UnknownError(Exception):
    pass

class Grid(list):
    """升级版二维网格：支持 grid[a] 直接访问坐标，其中a为元组"""
    def __getitem__(self, key):
        if isinstance(key, tuple):
            return super().__getitem__(key[0])[key[1]]
        return super().__getitem__(key)

    def __setitem__(self, key, value):
        if isinstance(key, tuple):
            super().__getitem__(key[0])[key[1]] = value
        else:
            super().__setitem__(key, value)

def fetch_slant(url="https://www.puzzle-slant.com/"):
    """
    输入划斜线网页链接（支持每日、特殊尺寸等任意页面），
    后台静默抓取并直接返回 (size, clues)
    - size: 正方形格子边长 (int)
    - clues: 顶点线索字典 {(r, c): num, ...}，坐标范围 0 <= r, c <= size
    """
    print(f"正在后台启动无头浏览器抓取划斜线页面: {url} ...")
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        page = browser.new_page()
        page.goto(url)

        # 核心等待：等棋盘格子与线索渲染就绪
        page.wait_for_selector(".slant-cell-back .cell")
        page.wait_for_selector(".task")

        data = page.evaluate("""() => {
            let cells = Array.from(document.querySelectorAll('.cell.selectable'));
            cells.sort((a, b) => a.offsetTop - b.offsetTop || a.offsetLeft - b.offsetLeft);

            let size = Math.round(Math.sqrt(cells.length));
            let c0 = cells[0].getBoundingClientRect();
            let c1 = cells[1].getBoundingClientRect();
            let step = c1.left - c0.left;
            let originX = c0.left;
            let originY = c0.top;

            let tasks = Array.from(document.querySelectorAll('.task'));
            let clues = {};

            tasks.forEach(t => {
                let rect = t.getBoundingClientRect();
                let cx = rect.left + rect.width / 2;
                let cy = rect.top + rect.height / 2;

                let c = Math.round((cx - originX) / step);
                let r = Math.round((cy - originY) / step);

                let txt = t.innerText.trim();
                if (txt !== "" && !isNaN(txt)) {
                    clues[`${r},${c}`] = parseInt(txt);
                }
            });

            return { size: size, clues: clues };
        }""")

        browser.close()

        # 转换为 Python 元组键的字典 {(r, c): num}
        clues = {
            tuple(map(int, k.split(','))): v 
            for k, v in data["clues"].items()
        }

        print(f"✔ 抓取成功！尺寸: {data['size']}x{data['size']}，共 {len(clues)} 个线索")
        return data["size"], clues

def show_slant(size, clues, grid):
    """
    划斜线 (Slant / Gokigen Naname) 专属高保真可视化器
    :param size: 正方形棋盘边长 (int, 格子数为 size x size)
    :param clues: 顶点线索字典 {(r, c): num, ...}，坐标 0 <= r, c <= size
    :param grid: 2D 矩阵 (1: 反斜线 , 0: 正斜线 /, -1: 未知紫色)
    """
    root = tk.Tk()
    root.title(f"Slant Solver Visualization ({size}x{size}) - [按住鼠标任意键可自由拖动画布]")

    # 1. 获取屏幕物理分辨率，做防爆屏窗口尺寸限制
    screen_w = root.winfo_screenwidth()
    screen_h = root.winfo_screenheight()

    # 格子像素大小（自适应缩放）
    cell_size = max(26, min(50, 780 // size))
    margin_x = 45
    margin_y = 45

    total_w = margin_x * 2 + cell_size * size
    total_h = margin_y * 2 + cell_size * size

    view_w = min(total_w + 30, int(screen_w * 0.82))
    view_h = min(total_h + 30, int(screen_h * 0.82))
    root.geometry(f"{view_w}x{view_h}+{(screen_w - view_w)//2}+{(screen_h - view_h)//2}")

    # 2. 创建带漫游滚动的画布系统
    frame = tk.Frame(root)
    frame.pack(fill=tk.BOTH, expand=True)

    canvas = tk.Canvas(frame, bg="#2B2B2B", scrollregion=(0, 0, total_w, total_h))
    h_bar = tk.Scrollbar(frame, orient=tk.HORIZONTAL, command=canvas.xview)
    v_bar = tk.Scrollbar(frame, orient=tk.VERTICAL, command=canvas.yview)
    canvas.configure(xscrollcommand=h_bar.set, yscrollcommand=v_bar.set)

    h_bar.pack(side=tk.BOTTOM, fill=tk.X)
    v_bar.pack(side=tk.RIGHT, fill=tk.Y)
    canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

    # 鼠标拖拽平移与滚轮绑定
    for btn in ("<ButtonPress-1>", "<ButtonPress-2>", "<ButtonPress-3>"):
        canvas.bind(btn, lambda e: canvas.scan_mark(e.x, e.y))
    for motion in ("<B1-Motion>", "<B2-Motion>", "<B3-Motion>"):
        canvas.bind(motion, lambda e: canvas.scan_dragto(e.x, e.y, gain=1))
    canvas.bind("<MouseWheel>", lambda e: canvas.yview_scroll(int(-1 * (e.delta / 120)), "units"))
    canvas.bind("<Shift-MouseWheel>", lambda e: canvas.xview_scroll(int(-1 * (e.delta / 120)), "units"))

    # 3. 绘制格子背景与斜线
    COLOR_PURPLE = "#C798F9"  # 未知格淡紫色
    COLOR_WHITE  = "#FFFFFF"  # 已定格白色
    COLOR_LINE   = "#111111"  # 斜线深黑
    COLOR_GRID   = "#8A8A8A"  # 浅灰细网格线

    line_width = max(2.5, cell_size * 0.08)

    for r in range(size):
        for c in range(size):
            x1 = margin_x + c * cell_size
            y1 = margin_y + r * cell_size
            x2 = x1 + cell_size
            y2 = y1 + cell_size

            state = grid[r][c]

            # 绘制底色
            bg = COLOR_PURPLE if state == -1 else COLOR_WHITE
            canvas.create_rectangle(x1, y1, x2, y2, fill=bg, outline=COLOR_GRID, width=1)

            # 绘制对角斜线
            if state == 1:
                # 1: 反斜线 \ (左上到右下)
                canvas.create_line(x1, y1, x2, y2, fill=COLOR_LINE, width=line_width, capstyle=tk.ROUND)
            elif state == 0:
                # 0: 正斜线 / (左下到右上)
                canvas.create_line(x1, y2, x2, y1, fill=COLOR_LINE, width=line_width, capstyle=tk.ROUND)

    # 4. 绘制棋盘外粗框
    canvas.create_rectangle(
        margin_x, margin_y,
        margin_x + size * cell_size, margin_y + size * cell_size,
        outline="#444444", width=2
    )

    # 5. 顶层绘制：顶点数字线索 (置顶确保完全不被斜线切断)
    circle_r = max(8, cell_size * 0.32)
    font_digit = ("Arial", max(9, int(cell_size * 0.35)), "bold")

    for (r, c), num in clues.items():
        cx = margin_x + c * cell_size
        cy = margin_y + r * cell_size

        # 米黄圆底 + 纯黑描边
        canvas.create_oval(
            cx - circle_r, cy - circle_r, cx + circle_r, cy + circle_r,
            fill="#FFF9C4", outline="#000000", width=1.8
        )
        # 居中黑色数字
        canvas.create_text(
            cx, cy, text=str(num), font=font_digit, fill="#000000"
        )

    # 6. 四周坐标刻度 (a..ad, 1..N)
    font_coord = ("Arial", max(8, int(cell_size * 0.3)), "normal")
    for c in range(size):
        col_letter = chr(ord('a') + c) if c < 26 else f"a{chr(ord('a') + c - 26)}"
        cx = margin_x + c * cell_size + cell_size / 2
        canvas.create_text(cx, margin_y - 18, text=col_letter, font=font_coord, fill="#999999")
        canvas.create_text(cx, margin_y + size * cell_size + 18, text=col_letter, font=font_coord, fill="#999999")

    for r in range(size):
        cy = margin_y + r * cell_size + cell_size / 2
        canvas.create_text(margin_x - 18, cy, text=str(r + 1), font=font_coord, fill="#999999")
        canvas.create_text(margin_x + size * cell_size + 18, cy, text=str(r + 1), font=font_coord, fill="#999999")

    root.mainloop()

