size,clues=fetch_slant('https://www.puzzle-slant.com/?size=10')

def main(size:int,clues:dict):
    grid=Grid([[-1]*size for _ in range(size)])

    def count_if_point(lo,lst=((-1,-1),(-1,0),(0,-1),(0,0)),grid=grid):#返回两个字典，第一个是坐标和相应的值，第二个统计lst里指向lo的(1)、反指向的(0)、-1的数量
        y,x=lo
        result1={}
        result={1:0,0:0,-1:0}
        for dy,dx in lst:
            if 0<=y+dy<size and 0<=x+dx<size:
                temp=grid[y+dy][x+dx]
                if temp==-1:
                    result1[(dy,dx)]=temp
                    result[-1]+=1
                else:
                    result1[(dy,dx)]=temp^(-dy)^(-dx)
                    result[temp^(-dy)^(-dx)]+=1
        return result1,result

    def modify(lo,lst,shi,grid=grid):#把lst里所有的偏移改成shi是否属于lo，lst示例为((-1,-1),(-1,0),(0,-1),(0,0))
        y,x=lo
        for dy,dx in lst:
            if 0<=y+dy<size and 0<=x+dx<size and grid[y+dy][x+dx]==-1:#防意外修改
                grid[y+dy][x+dx]=shi^(-dy)^(-dx)
    #这个可以不用effect
    def count_progress(size=size,grid=grid):
        result=0
        for y,x in product(range(size), range(size)):
            if grid[y][x]!=-1:
                result+=1
        return result

    progress=0
    last_progress=-1
    while progress>last_progress:
        last_progress=progress
        #主循环开始
        #单个查看
        for lo,number in clues.copy().items():#0和4会在第一个循环被处理掉然后被删掉，不用单独写
            y,x=lo
            _,couNT=count_if_point(lo)
            if couNT[-1]==0:
                del clues[lo]
                continue
            if couNT[1]+couNT[-1]==number:#-1同化成1，这种好像很久没写了；注意near的长度不一定是4
                modify(lo,((-1,-1),(-1,0),(0,-1),(0,0)),1)
            if couNT[1]==number:
                modify(lo,((-1,-1),(-1,0),(0,-1),(0,0)),0)
        #核心技巧：复调
        for lo,number in clues.copy().items():
            y,x=lo
            #不断往右看，在上下边缘时无效
            if y!=0 and y!=size:
                p=1
                du=clues[lo]
                _,yibian=count_if_point(lo,((-1,-1),(0,-1)))
                while (y,x+p) in clues:
                    du+=clues[(y,x+p)]
                    _,lingyibian=count_if_point((y,x+p),((-1,0),(0,0)))
                    if yibian[1]+lingyibian[1]+2*p==du:#度数已满
                        modify((y,x),((-1,-1),(0,-1)),0)
                        modify((y,x+p),((-1,0),(0,0)),0)
                        break
                    if yibian[1]+lingyibian[1]+yibian[-1]+lingyibian[-1]+2*p==du:#度数已空
                        modify((y,x),((-1,-1),(0,-1)),1)
                        modify((y,x+p),((-1,0),(0,0)),1)
                        break
                    p+=1
            #同理，不断往下看
            if x!=0 and x!=size:
                p=1
                du=clues[lo]
                _,yibian=count_if_point(lo,((-1,-1),(-1,0)))
                while (y+p,x) in clues:
                    du+=clues[(y+p,x)]
                    _,lingyibian=count_if_point((y+p,x),((0,-1),(0,0)))
                    if yibian[1]+lingyibian[1]+2*p==du:#度数已满
                        modify((y,x),((-1,-1),(-1,0)),0)
                        modify((y+p,x),((0,-1),(0,0)),0)
                        break
                    if yibian[1]+lingyibian[1]+yibian[-1]+lingyibian[-1]+2*p==du:#度数已空
                        modify((y,x),((-1,-1),(-1,0)),1)
                        modify((y+p,x),((0,-1),(0,0)),1)
                        break
                    p+=1
        #连通性，这里连通的是交点而不是格子；格式依然为[[成员,边界]]，其中边界与之前的定义不同，指成员中，周围还有未填格的格子；如果没有边界，说明这个连通已经连到边缘并结束了.往后看就能发现这个定义非常实用
        liantong=[]
        visited=set()
        for y,x in product(range(size+1), range(size+1)):
            if (y,x) not in visited:
                members=set()
                boundry=set()
                aaa={(y,x)}
                while aaa:
                    now=aaa.pop()
                    nei,neidict=count_if_point(now)
                    for i,j in nei.items():
                        lo=(now[0]+{-1:-1,0:1}[i[0]],now[1]+{-1:-1,0:1}[i[1]])
                        if j==1 and (lo not in members):
                            aaa.add(lo)  
                    members.add(now)
                    if neidict[-1]!=0:
                        boundry.add(now)
                    if now[0]==0 or now[0]==size or now[1]==0 or now[1]==size:
                        boundry.add((-1,-1))
                visited.update(members)
                liantong.append([members,boundry])
        #这也能冲破封锁？为避免动态问题，这里采用静态检查+最后统一更改
        modifylist=[]
        for members,boundry in liantong:
            if len(boundry)==1 and (-1,-1) not in boundry:
                a,=boundry
                #检查这个boundry是否只有一个出口
                couNTsqeicfic,couNT=count_if_point(a)
                if couNT[-1]==0:
                    raise UnknownError
                if couNT[-1]==1:
                    #找到这个-1
                    for b,c in couNTsqeicfic.items():
                        if c==-1:
                            modifylist.append((a,[b]))
                            break
        for lo,dire in modifylist:
            modify(lo,dire,1)
        #防止闭合
        for members, boundry in liantong:
            for loy, lox in boundry:
                if (loy+1,lox-1) in boundry and grid[loy][lox-1]==-1:
                    grid[loy][lox-1]=1
                if (loy+1,lox+1) in boundry and grid[loy][lox]==-1:
                    grid[loy][lox]=0
        #双单度不能相撞，最典型的就是中间1和1不能相连
        dying=set()#「将死之人」
        for members,boundry in liantong:
            if len(boundry)==1 and (-1,-1) not in boundry:
                a,=boundry
                if a not in clues:
                    continue
                number=clues[a]
                _,couNT=count_if_point(a)
                if number-couNT[1]==1:
                    dying.add(a)
        #dying之间不能相连
        modifylist=[]
        for loy,lox in dying:
            if (loy+1,lox-1) in dying:
                modifylist.append((loy,lox-1,1))
            if (loy+1,lox+1) in dying:
                modifylist.append((loy,lox,0))
        for a,b,c in modifylist:#grid[(a,b)]一定是-1，否则不会成为dying
            grid[a][b]=c
        #主循环结束
        progress=count_progress()
        print(progress)
    return clues,grid


_,grid=main(size,clues.copy())

show_slant(size, clues, grid)